import{_ as t,a as o,b as s,c as i,d as a,e as r}from"./chunks/AS-Apps-SA.CzVlwi0n.js";import{_ as n,o as l,c as p,a3 as u}from"./chunks/framework.g9mfNVRQ.js";const I=JSON.parse('{"title":"Paramètres Android","description":"","frontmatter":{"source_hash":"8a63383c39","source_commit":"e9ebf28"},"headers":[],"relativePath":"fr/troubleshoot/savings.md","filePath":"fr/troubleshoot/savings.md"}'),d={name:"fr/troubleshoot/savings.md"};function m(c,e,g,v,h,b){return l(),p("div",null,[...e[0]||(e[0]=[u('<p>Android propose de nombreuses options d&#39;économie d&#39;énergie. Elles sont utiles pour gagner en autonomie, mais elles peuvent facilement viser des fonctions indispensables à un système CGM.</p><p>Tous les réglages décrits ci-dessous se trouvent dans les paramètres Android de votre téléphone ; leur apparence varie beaucoup selon les personnalisations du fabricant.</p><img src="'+t+'" style="zoom:75%;"><h2 id="battery-saver" tabindex="-1">Économiseur de batterie <a class="header-anchor" href="#battery-saver" aria-label="Permalink to &quot;Économiseur de batterie {#battery-saver}&quot;">​</a></h2><p>En dessous d&#39;un certain niveau de batterie, Android arrête de nombreux services et empêche xDrip de fonctionner normalement. Gardez toujours une batterie externe sur vous pour éviter cette situation.</p><p>Pendant l&#39;utilisation normale du téléphone, assurez-vous qu&#39;il n&#39;est <strong>pas</strong> activé.</p><img src="'+o+'" style="zoom:75%;"><h2 id="apps-battery-savings" tabindex="-1">Économies de batterie des applications <a class="header-anchor" href="#apps-battery-savings" aria-label="Permalink to &quot;Économies de batterie des applications {#apps-battery-savings}&quot;">​</a></h2><p>Les économies de batterie peuvent être réglées pour chaque application du téléphone. En cas de problème, vérifiez-les attentivement. Cela s&#39;applique aussi à OOP, WatchDrip+ (si vous l&#39;utilisez) et au Bluetooth.</p><div class="warning custom-block"><p class="custom-block-title">Mises à jour d&#39;Android</p><p>Les mises à jour d&#39;Android peuvent rétablir ces réglages par défaut : vérifiez-les toujours après coup.</p></div><h4 id="android-10" tabindex="-1">Android 10 <a class="header-anchor" href="#android-10" aria-label="Permalink to &quot;Android 10 {#android-10}&quot;">​</a></h4><img src="'+s+'" style="zoom:75%;"><h4 id="android-11-and-above" tabindex="-1">Android 11 et plus récent <a class="header-anchor" href="#android-11-and-above" aria-label="Permalink to &quot;Android 11 et plus récent {#android-11-and-above}&quot;">​</a></h4><img src="'+i+'" style="zoom:75%;"><p>xDrip doit fonctionner sans restriction.</p><img src="'+a+'" style="zoom:75%;"><h3 id="bluetooth" tabindex="-1">Bluetooth <a class="header-anchor" href="#bluetooth" aria-label="Permalink to &quot;Bluetooth {#bluetooth}&quot;">​</a></h3><p>Vous trouverez probablement le Bluetooth dans les applications système (menu trois points).<br> Certains téléphones Android n&#39;affichent pas l&#39;application Bluetooth.</p><img src="'+r+'" style="zoom:75%;"><p>Le Bluetooth doit fonctionner sans restriction si xDrip se connecte directement à un capteur.</p><h2 id="xiaomi-miui-optimizations" tabindex="-1">Optimisations MIUI de Xiaomi <a class="header-anchor" href="#xiaomi-miui-optimizations" aria-label="Permalink to &quot;Optimisations MIUI de Xiaomi {#xiaomi-miui-optimizations}&quot;">​</a></h2><p>Les optimisations MIUI peuvent avoir un impact massif (négatif) sur la stabilité du système et la fiabilité de xDrip. Si vous constatez un nombre accru de « valeurs manquées » avec MIUI 14 (ou peut-être des versions de MIUI plus anciennes), essayez de désactiver les optimisations MIUI. Ce réglage se trouve dans les &amp;lt;Options pour les développeurs&gt;, masquées par défaut. Voici comment afficher les &amp;lt;Options pour les développeurs&gt; puis désactiver les optimisations MIUI.</p><h3 id="enable-developer-options" tabindex="-1">Activer les options pour les développeurs <a class="header-anchor" href="#enable-developer-options" aria-label="Permalink to &quot;Activer les options pour les développeurs {#enable-developer-options}&quot;">​</a></h3><p>Pour afficher les <strong>&amp;lt;Options pour les développeurs&gt;</strong>, procédez comme suit :</p><ol><li>Ouvrez les <strong>&amp;lt;Paramètres&gt;</strong> de votre smartphone.</li><li>Sélectionnez <strong>&amp;lt;À propos du téléphone&gt;</strong>.</li><li>Appuyez 7 fois sur <strong>&amp;lt;Version MIUI&gt;</strong> (première entrée de la liste).</li><li>Le message <strong>&amp;lt;Vous êtes maintenant développeur.&gt;</strong> s&#39;affiche.</li><li>L&#39;entrée <strong>&amp;lt;Paramètres&gt;</strong> -&gt; <strong>&amp;lt;Paramètres supplémentaires&gt;</strong> -&gt; <strong>&amp;lt;Options pour les développeurs&gt;</strong> est maintenant visible.</li></ol><h3 id="disable-xiaomi-miui-optimizations" tabindex="-1">Désactiver les optimisations MIUI de Xiaomi <a class="header-anchor" href="#disable-xiaomi-miui-optimizations" aria-label="Permalink to &quot;Désactiver les optimisations MIUI de Xiaomi {#disable-xiaomi-miui-optimizations}&quot;">​</a></h3><p>Pour désactiver les optimisations MIUI, vous devez d&#39;abord <strong>activer les options pour les développeurs</strong>. Procédez ensuite comme suit :</p><ol><li>Ouvrez les <strong>&amp;lt;Paramètres&gt;</strong> de votre smartphone.</li><li>Sélectionnez <strong>&amp;lt;Paramètres supplémentaires&gt;</strong> -&gt; <strong>&amp;lt;Options pour les développeurs&gt;</strong>.</li><li><strong>Uniquement pour MIUI 14 :</strong> sur MIUI 14, l&#39;option <strong>&amp;lt;Activer l&#39;optimisation MIUI&gt;</strong> n&#39;est <strong>PAS</strong> visible par défaut. Pour faire apparaître l&#39;option manquante, faites défiler jusqu&#39;à <strong>&amp;lt;SAISIE AUTOMATIQUE&gt;</strong> et appuyez plusieurs fois sur <strong>&amp;lt;Rétablir les valeurs par défaut&gt;</strong>. L&#39;option voulue apparaît alors.</li><li><strong>Désactivez</strong> l&#39;option <strong>&amp;lt;Activer l&#39;optimisation MIUI&gt;</strong> !</li><li>Redémarrez votre smartphone.</li></ol><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2023.02.26" target="_blank" rel="noreferrer"><em>Dernière modification le 6/03/2024</em></a></p>',30)])])}const z=n(d,[["render",m]]);export{I as __pageData,z as default};
